-- FLL-Naturteich · coverage wave block 3b (2026-09-29): GATE + EQUATION PROPOSALS that read the block-3a fields. SIGN-OFF REQUIRED (Alvaro):
-- every statement changes enforcement or a computed value (EQ-05 operand, REQ-33 re-host + operand, REQ-26 tightened, new REQ-34…REQ-42).
-- Quotes = rendered PDF pages read in-session 2026-09-29 (VA). Each item carries its print basis and its open RULING.
-- Apply ONLY after block 3a and after the rulings: node scripts/apply-migration.mjs scripts/migrations/20260929220100_fll_naturteich_gates_coverage_block3b.sql
-- Rollback: scripts/migrations/rollback-20260929220100_fll_naturteich_gates_coverage_block3b.sql
BEGIN;
-- EQ-05 (FLLNT-11): operand pool_underwater_surface (bottom + walls) → overflow_connected_water_surface_m2 (B-1, §10.3.1 p. 54–55). Guarded by the current formula.
UPDATE equations e SET formula = 'splash_water_tank_volume >= 150 * overflow_connected_water_surface_m2', input_symbols = ARRAY['splash_water_tank_volume','overflow_connected_water_surface_m2']::text[], description = COALESCE(e.description, '') || ' — Coverage block 3b (2026-09-29): operand corrected to the inundated water surface of the connected area (§10.3.1); was pool_underwater_surface (bottom + walls).', verification_quote = 'A water reservoir is mandatory when using rigid overflow weirs. […] The usable volume of the splash water tank must be dimensioned so that at least 150 l per square metre can be provided to the inundated water surface. […] In the case of multi-area systems, only the water surface of the area to which the overflow weir is connected is taken into account.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE e.worksheet_template_id = w.id AND w.code = 'FLLNT-11' AND s.code = 'FLL-Naturteich' AND e.equation_number = 'EQ-05' AND e.formula = 'splash_water_tank_volume >= 150 * pool_underwater_surface';
-- FLLNT-09 REQ-33 → re-hosted to FLLNT-11
-- §10.3.1 (p. 54–55): "at least 150 l per square metre … to the inundated water surface" / "only the water surface of the area to which the overflow weir is connected". The live operand pool_underwater_surface = bottom + walls (App. 5 colonisable surface) is not the water surface (B-1). Re-hosted from FLLNT-09 to FLLNT-11 where every input lives. Changes a computed comparison → sign-off; the operand itself is print-determined.
UPDATE compliance_requirements cr SET condition = 'IF rigid_overflow_used == true THEN splash_water_tank_volume >= 150 * overflow_connected_water_surface_m2', worksheet_template_id = (SELECT w2.id FROM worksheet_templates w2 WHERE w2.standard_id = s.id AND w2.code = 'FLLNT-11'), source_quote = '§10.3.1 (p. 54–55): "at least 150 l per square metre … to the inundated water surface" / "only the water surface of the area to which the overflow weir is connected". The live operand pool_underwater_surface = bottom + walls (App. 5 colonisable surface) is not the water surface (B-1). Re-hosted from FLLNT-09 to FLLNT-11 where every input lives. Changes a computed comparison → sign-off; the operand itself is print-determined.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLLNT-09' AND s.code = 'FLL-Naturteich' AND cr.code = 'REQ-33' AND cr.condition = 'IF rigid_overflow_used == true THEN splash_water_tank_volume >= 150 * pool_underwater_surface';
-- FLLNT-13 REQ-26
-- §11.1 (p. 59): the acceptance is the purchaser's acceptance of the work; an empty defects field is not an acceptance (B-3). Tightens enforcement → sign-off.
UPDATE compliance_requirements cr SET condition = 'acceptance_passed == true', source_quote = '§11.1 (p. 59): the acceptance is the purchaser''s acceptance of the work; an empty defects field is not an acceptance (B-3). Tightens enforcement → sign-off.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLLNT-13' AND s.code = 'FLL-Naturteich' AND cr.code = 'REQ-26' AND cr.condition = 'acceptance_passed == true OR defects_noted IS EMPTY';
-- FLLNT-11 REQ-34 (new, block) — Table cell of the type definition ("< 10 h/day") → block (RULING: the type tables are definitions, not "must" sentences).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-34', 'Typ II — Oberflächenabzug im Intervallbetrieb < 10 h/Tag (Tab. 3)', 'Type II — surface discharge in interval operation < 10 h/day (Tab. 3)', 'IF natural_pool_type == type_II THEN surface_discharge_hours_per_day < 10', '§5 / Tab.3', 'block', 'Coverage block 3b (2026-09-29): Table cell of the type definition ("< 10 h/day") → block (RULING: the type tables are definitions, not "must" sentences).', 'Table 3 (Type II), Filter operation/warm water circulation during the swimming season: "no filter available · surface water discharge in interval operation < 10 h/day"', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLNT-11' AND s.code = 'FLL-Naturteich'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLLNT-11 REQ-35 (new, block) — Table cells ("> 25%", "> 80%") → block (RULING as REQ-34). Type V prints "filtration rate" where IV prints "filter feed rate" — read as the same quantity (RULING).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-35', 'Filterbeschickung in % des Gesamtwasservolumens — Typ III > 25 % · Typ IV/V > 80 % (Tab. 4–6)', 'Filter feed rate as % of total water volume — Type III > 25 % · Type IV/V > 80 % (Tab. 4–6)', '(IF natural_pool_type == type_III THEN feed_share_of_volume_pct > 25) AND (IF natural_pool_type IN {type_IV, type_V} THEN feed_share_of_volume_pct > 80)', '§5 / Tab.4 / Tab.5 / Tab.6', 'block', 'Coverage block 3b (2026-09-29): Table cells ("> 25%", "> 80%") → block (RULING as REQ-34). Type V prints "filtration rate" where IV prints "filter feed rate" — read as the same quantity (RULING).', 'Table 4 (Type III), Filter operation/warm water circulation during the swimming season: "operation of surface discharge depending on design · filter feed rate > 25% of the total water volume/day · filter operation > 12 h/day · maximum downtime 1 h" — Table 5 (Type IV): "filter feed rate > 80% of the total water volume/day · filter operation 24 h/day" — Table 6 (Type V): "filtration rate > 80% of the total water volume/day · filter operation 24 h/day"', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLNT-11' AND s.code = 'FLL-Naturteich'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLLNT-11 REQ-36 (new, block) — Table cells → block (RULING as REQ-34).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-36', 'Filterbetrieb — Typ III > 12 h/Tag, Stillstand ≤ 1 h · Typ IV/V 24 h/Tag (Tab. 4–6)', 'Filter operation — Type III > 12 h/day, downtime ≤ 1 h · Type IV/V 24 h/day (Tab. 4–6)', '(IF natural_pool_type == type_III THEN filter_operation_hours_per_day > 12 AND filter_max_downtime_h <= 1) AND (IF natural_pool_type IN {type_IV, type_V} THEN filter_operation_hours_per_day == 24)', '§5 / Tab.4 / Tab.5 / Tab.6', 'block', 'Coverage block 3b (2026-09-29): Table cells → block (RULING as REQ-34).', 'Table 4 (Type III), Filter operation/warm water circulation during the swimming season: "operation of surface discharge depending on design · filter feed rate > 25% of the total water volume/day · filter operation > 12 h/day · maximum downtime 1 h" — Table 5 (Type IV): "filter feed rate > 80% of the total water volume/day · filter operation 24 h/day" — Table 6 (Type V): "filtration rate > 80% of the total water volume/day · filter operation 24 h/day"', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLNT-11' AND s.code = 'FLL-Naturteich'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLLNT-06 REQ-37 (new, block) — "therefrom at least half" → ≥ 50 % of the regeneration area; submerged_hydrobot_share_calc (FLLNT-06-D4) already computes it, the comparison was STAGED and never live (A-9). Block (RULING as REQ-34).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-37', 'Typ I/II — mindestens die Hälfte des Regenerationsbereichs als submerses hydrobotanisches System (Tab. 2/3)', 'Type I/II — at least half of the regeneration area as submerged hydrobotanical system (Tab. 2/3)', 'IF natural_pool_type IN {type_I, type_II} THEN submerged_hydrobot_share_calc >= 50', '§5 / Tab.2 / Tab.3', 'block', 'Coverage block 3b (2026-09-29): "therefrom at least half" → ≥ 50 % of the regeneration area; submerged_hydrobot_share_calc (FLLNT-06-D4) already computes it, the comparison was STAGED and never live (A-9). Block (RULING as REQ-34).', 'Table 2 (Type I) / Table 3 (Type II), Regeneration area in % of the total water area: "> 50% therefrom at least half as submerged hydrobotanical system"', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLNT-06' AND s.code = 'FLL-Naturteich'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLLNT-07 REQ-38 (new, block) — "can be tolerated" / "are not permitted" → block (RULING: on concrete the print demands crease-free — the gate accepts the concrete declaration as the crease-free case; a measured-creases-on-concrete state is not modelled).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-38', 'Folien/Bahnen in Sichtbereichen — Faltenregel §9.3 (1,0 cm / 2,0 m / 2,0 m, keine Kreuzungen)', 'Synthetic/elastomer liners in visible areas — crease rule §9.3 (1.0 cm / 2.0 m / 2.0 m, no crossings)', 'IF sealing_type IN {EPDM, PVC} THEN (liner_on_concrete_base == true) OR (crease_height_max_cm <= 1.0 AND crease_length_max_m <= 2.0 AND crease_min_distance_m >= 2.0 AND creases_crossing == false)', '§9.3', 'block', 'Coverage block 3b (2026-09-29): "can be tolerated" / "are not permitted" → block (RULING: on concrete the print demands crease-free — the gate accepts the concrete declaration as the crease-free case; a measured-creases-on-concrete state is not modelled).', 'Synthetic and elastomer liners in visible areas: are to be installed crease-free on level and stable subsoil (e.g. made of concrete); if concrete has not been applied to the subsoil, creases with a height of up to 1.0 cm and a length of up to 2.0 m with a minimum distance of 2.0 m from each other can be tolerated. Creases are not permitted to cross over each other. These specifications apply to the natural pool when it is filled. Creases cannot hinder the use of maintenance equipment;', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLNT-07' AND s.code = 'FLL-Naturteich'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLLNT-07 REQ-39 (new, block) — "There must be at least one" → block.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-39', 'Mindestens eine Ein-/Ausstiegsstelle im Schwimmbereich (§9.5.3)', 'At least one entry/exit point in the swimming area (§9.5.3)', 'entry_exit_point_count >= 1', '§9.5.3', 'block', 'Coverage block 3b (2026-09-29): "There must be at least one" → block.', 'They must be safe to walk on and have a non-slip finish. Routine care and maintenance must be ensured. There must be at least one entry/exit point in the swimming area.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLNT-07' AND s.code = 'FLL-Naturteich'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLLNT-11 REQ-40 (new, block) — "are to be installed in a manner that" → block. overflow_tolerance_violations (FLLNT-11-D2) counts register rows over the printed tolerance; an empty register yields 0 (RULING whether ≥ 1 device row must exist). The scalar overflow_horizontal_tolerance_mm stays uncompared (legacy Plan-1 field).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-40', 'Überlaufkanten — horizontale Abweichung ≤ ±2 mm (≤ ±1 mm bis 1 m Kantenlänge) (§10.3.1)', 'Overflow edges — horizontal deviation ≤ ±2 mm (≤ ±1 mm for edges up to 1 m) (§10.3.1)', 'overflow_tolerance_violations == 0', '§10.3.1', 'block', 'Coverage block 3b (2026-09-29): "are to be installed in a manner that" → block. overflow_tolerance_violations (FLLNT-11-D2) counts register rows over the printed tolerance; an empty register yields 0 (RULING whether ≥ 1 device row must exist). The scalar overflow_horizontal_tolerance_mm stays uncompared (legacy Plan-1 field).', 'Overflow weirs are to be installed in a manner that the overflow edge does not deviate horizontally by more than +/- 2 mm or for overflow edges up to 1 m, by more than +/- 1 mm.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLNT-11' AND s.code = 'FLL-Naturteich'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLLNT-11 REQ-41 (new, warn) — "As a guide … can be used" → warn. overflow_edge_length (EQ-04) is the required guide length (0.01 · swimming_area_m2); overflow_edge_length_total (FLLNT-11-D1) is the installed Σ over the register.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-41', 'Überlaufkantenlänge — Richtwert 1 % der Schwimmbereichsfläche (§10.3.1)', 'Overflow edge length — guide value 1 % of the swimming-area surface (§10.3.1)', 'overflow_edge_length_total >= overflow_edge_length', '§10.3.1', 'warn', 'Coverage block 3b (2026-09-29): "As a guide … can be used" → warn. overflow_edge_length (EQ-04) is the required guide length (0.01 · swimming_area_m2); overflow_edge_length_total (FLLNT-11-D1) is the installed Σ over the register.', 'As a guide for the required length of overflow edge, the following value can be used for flexible and rigid overflow weirs depending on the shape and type of the natural pool: 1% of the surface area of the swimming area in metres. Example: Swimming area 30 m², 1% of 30 = 0.3 i. e. length of the overflow edge 0.3 m.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLNT-11' AND s.code = 'FLL-Naturteich'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLLNT-13 REQ-42 (new, block) — "must inform … no later than 3 working days" → block. Field exists (required) but was never compared (A-66).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-42', 'Fertigstellungsanzeige spätestens 3 Werktage vorher (§11.1)', 'Completion notice no later than 3 working days in advance (§11.1)', 'completion_notice_days_advance >= 3', '§11.1', 'block', 'Coverage block 3b (2026-09-29): "must inform … no later than 3 working days" → block. Field exists (required) but was never compared (A-66).', 'The supplier must inform the purchaser of pending completion dates no later than 3 working days before the respective completion date.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLNT-13' AND s.code = 'FLL-Naturteich'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
COMMIT;
